css:
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --ink: #111009;
  --ink2: #4a4740;
  --ink3: #8a8780;
  --paper: #faf9f6;
  --paper2: #f2f0eb;
  --paper3: #e8e5de;
  --line: #dedad2;

  --amber: #184e30;
  --amber-rgb: 24, 78, 48;
  --amber-light: #eff8f3;
  --amber-light-rgb: 239, 248, 243;
  --amber-mid: #64937a;
  --amber-mid-rgb: 100, 147, 122;
  --amber-ink: #163e25;
  --amber-ink-rgb: 22, 62, 37;
  --teal: #1a5c38;
  --teal-rgb: 26, 92, 56;
  --teal-light: #e8f5ee;
  --teal-light-rgb: 232, 245, 238;
  --teal-mid: #8bb09c;
  --teal-mid-rgb: 139, 176, 156;
  --rose: #17472b;
  --rose-rgb: 23, 71, 43;
  --rose-light: #ecf7f1;
  --rose-light-rgb: 236, 247, 241;
  --rose-mid: #81a893;
  --rose-mid-rgb: 129, 168, 147;}

html { scroll-behavior: smooth; }
/* PAGE MAX WIDTH */
nav, .hero, section, footer {
  max-width: 1600px;
  margin-left: auto;
  margin-right: auto;
}


body {
  background: var(--paper);
  color: var(--ink);
  font-family: 'Instrument Sans', sans-serif;
  font-size: 15px;
  line-height: 1.65;
}

nav {
  position: sticky; top: 0; z-index: 50;
  background: var(--paper);
  border-bottom: 1px solid var(--line);
  padding: 0 48px;
  height: 52px;
  display: flex; align-items: center; justify-content: space-between;
}
.nav-back {
  display: flex; align-items: center; gap: 8px;
  font-size: 13px; color: var(--ink3);
  text-decoration: none;
  font-family: 'JetBrains Mono', monospace;
  transition: color 0.15s;
}
.nav-back:hover { color: var(--ink); }
.nav-badge {
  font-family: 'JetBrains Mono', monospace;
  font-size: 11px; color: var(--teal);
  background: var(--teal-light);
  padding: 3px 10px; border-radius: 3px;
  letter-spacing: 0.05em;
}


.hero-tag {
  font-family: 'JetBrains Mono', monospace;
  font-size: 11px; letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--ink3);
  margin-bottom: 20px;
  display: flex; align-items: center; gap: 12px;
}

h1 {
  font-family: 'Fraunces', serif;
  font-size: 56px; font-weight: 300;
  line-height: 1.05; letter-spacing: -0.025em;
  color: var(--ink); margin-bottom: 24px;
}
h1 em { font-style: italic; color: var(--amber); }
.hero-desc { font-size: 17px; color: var(--ink2); line-height: 1.75; max-width: 480px; }

.meta-item {
  display: flex; flex-direction: column; gap: 4px;
  padding: 18px 20px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--paper2);
}
.meta-label { font-family: 'JetBrains Mono', monospace; font-size: 10px; letter-spacing: 0.1em; text-transform: uppercase; color: var(--ink3); }
.meta-value { font-size: 14px; color: var(--ink); font-weight: 500; }

/* ── HERO ── */
.hero {
  background: linear-gradient(135deg, var(--paper) 60%, var(--teal-light) 100%);
  padding: 48px 48px 40px;
  border-bottom: 1px solid var(--line);
  position: relative; overflow: hidden;
}
.hero .float-svg {
  position: absolute; right: 48px; top: 50%;
  transform: translateY(-50%);
  width: 160px; height: 160px;
  color: var(--teal); opacity: 0.25;
  pointer-events: none;
}
.hero .float-svg svg { width: 100%; height: 100%; display: block; }
.hero-tag {
  font-family: 'JetBrains Mono', monospace;
  font-size: 11px; letter-spacing: 0.12em;
  text-transform: uppercase; color: var(--ink3);
  margin-bottom: 12px; position: relative; z-index: 1;
}
h1 {
  font-family: 'Fraunces', serif;
  font-size: 52px; font-weight: 300;
  line-height: 1.1; letter-spacing: -0.025em;
  color: var(--ink); margin-bottom: 12px;
  position: relative; z-index: 1;
}
h1 em { font-style: italic; color: var(--teal); }
.hero-desc {
  font-size: 16px; color: var(--ink2);
  line-height: 1.75; max-width: 520px;
  margin-bottom: 20px; position: relative; z-index: 1;
}
.meta-inline {
  display: flex; gap: 24px; flex-wrap: wrap;
  position: relative; z-index: 1;
}
.m-item { display: flex; flex-direction: column; gap: 1px; }
.m-label {
  font-family: 'JetBrains Mono', monospace;
  font-size: 9px; letter-spacing: 0.08em;
  text-transform: uppercase; color: var(--ink3);
}
.m-value { font-size: 12px; color: var(--ink); font-weight: 500; }

section { padding: 64px 48px; border-bottom: 1px solid var(--line); }
.section-label {
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px; letter-spacing: 0.14em;
  text-transform: uppercase; color: var(--ink3);
  margin-bottom: 32px;
  display: flex; align-items: center; gap: 16px;
}
.section-label span { padding: 2px 8px; border: 1px solid var(--line); border-radius: 3px; }
.section-label::after { content: ''; flex: 1; height: 1px; background: var(--line); }
h2 { font-family: 'Fraunces', serif; font-size: 32px; font-weight: 300; letter-spacing: -0.015em; color: var(--ink); margin-bottom: 16px; }
.prose { font-size: 15px; color: var(--ink2); line-height: 1.8; max-width: 680px; }
.prose + .prose { margin-top: 12px; }

.scenarios { display: grid; grid-template-columns: repeat(3,1fr); gap: 12px; margin-top: 32px; }
.scenario-card {
  padding: 20px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--paper);
  opacity: 0; transform: translateY(12px);
  animation: fadeUp 0.4s ease forwards;
}
.scenario-card:nth-child(1) { animation-delay: 0.05s; }
.scenario-card:nth-child(2) { animation-delay: 0.12s; }
.scenario-card:nth-child(3) { animation-delay: 0.19s; }
.scenario-card:nth-child(4) { animation-delay: 0.26s; }
.scenario-card:nth-child(5) { animation-delay: 0.33s; }
.scenario-card:nth-child(6) { animation-delay: 0.40s; }
@keyframes fadeUp { to { opacity: 1; transform: translateY(0); } }
.sc-icon { font-size: 22px; margin-bottom: 10px; }
.sc-title { font-size: 13px; font-weight: 600; color: var(--ink); margin-bottom: 6px; }
.sc-desc { font-size: 12px; color: var(--ink3); line-height: 1.55; }

/* ── FUNNEL VISUAL ── */
.funnel-wrap { margin-top: 40px; max-width: 860px; }
.funnel-container {
  display: flex;
  flex-direction: column;
  gap: 0;
  align-items: stretch;
}
.funnel-level {
  display: flex;
  justify-content: center;
  align-items: stretch;
  gap: 16px;
  position: relative;
}
.funnel-shape {
  width: 100%;
  max-width: var(--funnel-width, 100%);
  padding: 18px 24px;
  display: flex;
  align-items: center;
  gap: 16px;
  min-height: 74px;
  position: relative;
  border-radius: 4px;
}
/* Each level narrows toward the bottom to form a true funnel */
.funnel-level.level-1 { --funnel-width: 100%; }
.funnel-level.level-2 { --funnel-width: 93%; }
.funnel-level.level-3 { --funnel-width: 84%; }
.funnel-level.level-4 { --funnel-width: 72%; }
.funnel-level.level-5 { --funnel-width: 61%; }

.funnel-level.level-1 .funnel-shape { background: rgba(var(--amber-light-rgb), 0.55); border: 1px solid rgba(var(--amber-rgb), 0.24); }
.funnel-level.level-2 .funnel-shape { background: rgba(var(--amber-light-rgb), 0.92); border: 1px solid rgba(var(--amber-rgb), 0.32); }
.funnel-level.level-3 .funnel-shape { background: rgba(var(--teal-light-rgb), 0.96); border: 1px solid rgba(var(--teal-rgb), 0.28); }
.funnel-level.level-4 .funnel-shape { background: rgba(var(--teal-mid-rgb), 0.28); border: 1px solid rgba(var(--amber-ink-rgb), 0.38); }
.funnel-level.level-5 .funnel-shape { background: rgba(var(--amber-mid-rgb), 0.74); border: 1px solid var(--amber-ink); }

.funnel-q-num {
  font-family: 'JetBrains Mono', monospace;
  font-size: 11px; font-weight: 500;
  width: 24px; flex-shrink: 0;
  color: var(--amber);
}
.funnel-level.level-4 .funnel-q-num,
.funnel-level.level-5 .funnel-q-num { color: var(--ink); }
.funnel-level.level-4 .funnel-q-en,
.funnel-level.level-5 .funnel-q-en {
  color: var(--amber-ink);
}
.funnel-level.level-4 .funnel-q-depth,
.funnel-level.level-5 .funnel-q-depth {
  color: rgba(var(--amber-ink-rgb), 0.84);
}
.funnel-level.level-4 .funnel-example,
.funnel-level.level-5 .funnel-example {
  background: rgba(255,255,255,0.8);
  border-color: rgba(var(--amber-ink-rgb),0.08);
}
.funnel-level.level-4 .funnel-example-label,
.funnel-level.level-5 .funnel-example-label {
  color: var(--amber-ink);
}

.funnel-q-main {
  flex: 1;
}
.funnel-q-cn {
  font-family: 'Fraunces', serif;
  font-size: 16px; font-weight: 400;
  color: var(--ink);
  line-height: 1.2;
  margin-bottom: 2px;
}
.funnel-q-en {
  font-family: 'JetBrains Mono', monospace;
  font-size: 9px; letter-spacing: 0.08em;
  color: var(--ink3);
}
.funnel-q-depth {
  font-size: 11px; color: var(--ink3);
  font-style: italic;
  margin-top: 4px;
}
.funnel-example {
  width: 220px;
  flex-shrink: 0;
  padding: 10px 14px;
  background: rgba(255,255,255,0.6);
  border-radius: 6px;
  border: 1px solid rgba(0,0,0,0.06);
}
.funnel-example-label {
  font-family: 'JetBrains Mono', monospace;
  font-size: 9px; letter-spacing: 0.08em; text-transform: uppercase;
  color: var(--ink3); margin-bottom: 5px;
}
.funnel-example-q {
  font-size: 12px; color: var(--ink2);
  font-style: italic;
  line-height: 1.5;
}

.funnel-level.level-1 .funnel-example { width: 236px; }
.funnel-level.level-2 .funnel-example { width: 220px; }
.funnel-level.level-3 .funnel-example { width: 196px; }

.funnel-level.level-4 .funnel-shape,
.funnel-level.level-5 .funnel-shape {
  display: grid;
  grid-template-columns: 24px 1fr;
  align-items: start;
  row-gap: 10px;
  column-gap: 14px;
}

.funnel-level.level-4 .funnel-q-main,
.funnel-level.level-5 .funnel-q-main,
.funnel-level.level-4 .funnel-example,
.funnel-level.level-5 .funnel-example {
  grid-column: 2;
}

.funnel-level.level-4 .funnel-example,
.funnel-level.level-5 .funnel-example {
  width: 100%;
  max-width: none;
}

.funnel-arrow-down {
  text-align: center;
  font-size: 14px;
  color: var(--amber-mid);
  padding: 2px 0;
  line-height: 1;
}

.funnel-bottom {
  margin-top: 16px;
  padding: 16px 20px;
  background: var(--teal-light);
  border: 1px solid var(--teal-mid);
  border-radius: 8px;
  display: flex; align-items: center; gap: 14px;
}
.funnel-bottom-icon { font-size: 20px; }
.funnel-bottom-text { font-size: 13px; color: var(--teal); line-height: 1.6; }
.funnel-bottom-text strong { font-weight: 600; }

/* ── HISTORY/CASE/STEPS ── */
.timeline { margin-top: 40px; position: relative; }
.timeline::before { content: ''; position: absolute; left: 80px; top: 0; bottom: 0; width: 1px; background: var(--line); }
.tl-item { display: flex; gap: 32px; margin-bottom: 36px; position: relative; }
.tl-year { font-family: 'Fraunces', serif; font-size: 20px; font-weight: 300; color: var(--amber); width: 80px; flex-shrink: 0; text-align: right; padding-top: 2px; }
.tl-dot { position: absolute; left: 74px; top: 10px; width: 12px; height: 12px; border-radius: 50%; background: var(--amber); border: 2px solid var(--paper); box-shadow: 0 0 0 1px var(--amber-mid); z-index: 2; }
.tl-content { padding-top: 2px; }
.tl-event { font-size: 14px; font-weight: 600; color: var(--ink); margin-bottom: 4px; }
.tl-detail { font-size: 13px; color: var(--ink3); line-height: 1.6; max-width: 520px; }

.case-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; margin-top: 40px; }
.case-header { grid-column: 1 / -1; padding: 28px; background: var(--ink); border-radius: 10px; color: white; display: flex; align-items: center; justify-content: space-between; }
.case-company { font-family: 'Fraunces', serif; font-size: 36px; font-weight: 300; letter-spacing: -0.02em; }
.case-subtitle { font-size: 14px; color: rgba(255,255,255,0.5); margin-top: 6px; }
.case-year-badge { font-family: 'JetBrains Mono', monospace; font-size: 11px; background: rgba(255,255,255,0.12); padding: 6px 14px; border-radius: 4px; color: rgba(255,255,255,0.7); }
.case-panel { padding: 24px; border: 1px solid var(--line); border-radius: 10px; background: var(--paper); }
.panel-head { display: flex; align-items: center; gap: 10px; margin-bottom: 16px; }
.panel-icon { width: 32px; height: 32px; border-radius: 6px; display: flex; align-items: center; justify-content: center; font-size: 16px; flex-shrink: 0; }
.pi-teal { background: var(--teal-light); }
.pi-rose { background: var(--rose-light); }
.pi-amber { background: var(--amber-light); }
.panel-title { font-size: 13px; font-weight: 600; color: var(--ink); }
.panel-items { display: flex; flex-direction: column; gap: 8px; }
.pi-item { display: flex; gap: 10px; align-items: flex-start; font-size: 13px; color: var(--ink2); }
.pi-bullet { width: 18px; height: 18px; border-radius: 50%; flex-shrink: 0; display: flex; align-items: center; justify-content: center; font-size: 9px; font-weight: 600; margin-top: 2px; }
.bullet-teal { background: var(--teal-light); color: var(--teal); }
.bullet-rose { background: var(--rose-light); color: var(--rose); }
.bullet-amber { background: var(--amber-light); color: var(--amber); }
.case-vpc-full { grid-column: 1 / -1; border: 1px solid var(--line); border-radius: 10px; padding: 28px; background: var(--paper); }
.cvf-title { font-size: 13px; font-weight: 600; color: var(--ink); margin-bottom: 20px; }
.cvf-grid { display: grid; grid-template-columns: 1fr 24px 1fr; gap: 0; align-items: center; }
.cvf-half { display: flex; flex-direction: column; gap: 0; }
.cvf-section { padding: 16px 20px; border: 1px solid var(--line); }
.cvf-section:first-child { border-radius: 8px 8px 0 0; }
.cvf-section:last-child { border-radius: 0 0 8px 8px; border-top: none; }
.cvf-section-label { font-family: 'JetBrains Mono', monospace; font-size: 10px; letter-spacing: 0.08em; text-transform: uppercase; margin-bottom: 8px; }
.cvf-chips { display: flex; flex-wrap: wrap; gap: 6px; }
.chip { font-size: 12px; padding: 4px 10px; border-radius: 4px; line-height: 1.4; }
.chip-teal { background: var(--teal-light); color: var(--teal); }
.chip-rose { background: var(--rose-light); color: var(--rose); }
.chip-amber { background: var(--amber-light); color: var(--amber); }
.cvf-arrow { display: flex; flex-direction: column; align-items: center; gap: 4px; font-size: 18px; color: var(--amber-mid); }
.cvf-match-row { grid-column: 1 / -1; margin-top: 20px; padding: 16px 20px; background: var(--amber-light); border-radius: 8px; border: 1px solid var(--amber-mid); display: flex; align-items: center; gap: 16px; }
.cmr-icon { font-size: 20px; }
.cmr-text { font-size: 13px; color: var(--ink2); line-height: 1.6; }
.cmr-text strong { color: var(--amber); font-weight: 600; }

.steps-grid { display: grid; grid-template-columns: repeat(5,1fr); gap: 0; margin-top: 32px; }
.step-item { padding: 20px 16px; border-right: 1px solid var(--line); position: relative; }
.step-item:last-child { border-right: none; }
.step-num { font-family: 'Fraunces', serif; font-size: 32px; font-weight: 300; color: var(--paper3); line-height: 1; margin-bottom: 8px; }
.step-title { font-size: 12px; font-weight: 600; color: var(--ink); margin-bottom: 6px; }
.step-desc { font-size: 11px; color: var(--ink3); line-height: 1.55; }
.step-arrow { position: absolute; right: -10px; top: 50%; transform: translateY(-50%); font-size: 16px; color: var(--line); z-index: 2; background: var(--paper); padding: 2px 0; }
.step-item:last-child .step-arrow { display: none; }

.tips-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-top: 32px; }
.tip-card { padding: 20px; border-radius: 8px; border: 1px solid var(--line); }
.tip-card.do { background: var(--teal-light); border-color: var(--teal-mid); }
.tip-card.dont { background: var(--rose-light); border-color: var(--rose-mid); }
.tip-badge { font-family: 'JetBrains Mono', monospace; font-size: 10px; letter-spacing: 0.1em; text-transform: uppercase; margin-bottom: 12px; font-weight: 500; }
.do .tip-badge { color: var(--teal); }
.dont .tip-badge { color: var(--rose); }
.tip-list { display: flex; flex-direction: column; gap: 8px; }
.tip-row { display: flex; gap: 8px; font-size: 13px; line-height: 1.5; }
.do .tip-row { color: var(--teal); }
.dont .tip-row { color: var(--rose); }
.tip-icon { flex-shrink: 0; font-size: 14px; }

footer {
  padding: 48px 48px 40px;
  text-align: center;
  border-top: 1px solid var(--line);
  background: var(--paper);
}
.fc-progress-row {
  display: flex; align-items: center; justify-content: center;
  gap: 3px; margin-bottom: 24px; flex-wrap: wrap;
}
.fc-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--line); flex-shrink: 0; }
.fc-dot.visited { background: var(--teal); opacity: 0.4; }
.fc-dot.current { background: var(--teal); width: 20px; border-radius: 3px; }
.fc-ell {
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px; color: var(--ink3); margin: 0 4px;
}
.fc-progress-label {
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px; color: var(--ink3);
  margin-bottom: 20px; letter-spacing: 0.08em;
}
.fc-next-link {
  display: inline-flex; flex-direction: column; align-items: center;
  gap: 8px; padding: 24px 40px;
  border: 1px solid var(--teal); border-radius: 10px;
  background: var(--teal-light); transition: all 0.2s;
  text-decoration: none;
}
.fc-next-link:hover { background: var(--teal); }
.fc-next-link:hover .fc-nl-title,
.fc-next-link:hover .fc-nl-label,
.fc-next-link:hover .fc-nl-arrow { color: white; }
.fc-nl-label {
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px; letter-spacing: 0.1em; text-transform: uppercase;
  color: var(--teal); transition: color 0.2s;
}
.fc-nl-title {
  font-family: 'Fraunces', serif;
  font-size: 22px; font-weight: 300; color: var(--ink); transition: color 0.2s;
}
.fc-nl-arrow { font-size: 18px; color: var(--teal); transition: color 0.2s, transform 0.2s; }
.fc-next-link:hover .fc-nl-arrow { transform: translateX(4px); }
.fc-bottom {
  margin-top: 32px;
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px; color: var(--ink3); opacity: 0.5;
}

@media (max-width: 900px) {

  h1 { font-size: 38px; }
  section { padding: 40px 20px; }
  nav { padding: 0 20px; }
  footer { padding: 32px 20px 28px; }
  .fc-next-link { padding: 20px 24px; }
  .fc-nl-title { font-size: 18px; }
  .scenarios { grid-template-columns: 1fr 1fr; }
  .funnel-example { display: none; }
  .steps-grid { grid-template-columns: repeat(3,1fr); }
  .case-grid { grid-template-columns: 1fr; }
  .tips-grid { grid-template-columns: 1fr; }
  .cvf-grid { grid-template-columns: 1fr; }
  .cvf-arrow { display: none; }
}

.five-q-steps { display: flex; flex-direction: column; gap: 0; margin-top: 32px; }
.five-q-step { display: grid; grid-template-columns: 40px 1fr; gap: 20px; padding: 20px 0; border-bottom: 1px solid var(--line); }
.five-q-step:last-child { border-bottom: none; }
.five-q-num { width: 32px; height: 32px; border-radius: 50%; background: var(--paper2); border: 1px solid var(--line); display: flex; align-items: center; justify-content: center; font-family: 'Fraunces', serif; font-size: 14px; color: var(--ink3); flex-shrink: 0; margin-top: 2px; }
.five-q-type { font-family: 'JetBrains Mono', monospace; font-size: 10px; letter-spacing: 0.1em; text-transform: uppercase; color: var(--ink3); margin-bottom: 8px; }
.five-q-question { font-size: 14px; font-weight: 600; color: var(--ink); margin-bottom: 10px; }
.five-q-answer { font-size: 13px; color: var(--ink3); line-height: 1.65; font-style: italic; margin-bottom: 10px; padding: 10px 14px; background: var(--paper2); border-radius: 6px; border-left: 3px solid var(--line); }
.five-q-insight { font-size: 13px; color: var(--ink2); background: var(--amber-light); padding: 8px 12px; border-radius: 6px; border-left: 3px solid var(--amber); }
.five-q-insight::before { content: '洞察 → '; font-family: 'JetBrains Mono', monospace; font-size: 9px; letter-spacing: 0.1em; text-transform: uppercase; color: var(--amber); font-style: normal; }
.five-q-result { margin-top: 24px; padding: 24px 28px; background: var(--teal-light); border: 1px solid var(--teal-mid); border-radius: 10px; }
.five-q-result-label { font-family: 'JetBrains Mono', monospace; font-size: 10px; letter-spacing: 0.1em; text-transform: uppercase; color: var(--teal); margin-bottom: 10px; }
.five-q-result-text { font-size: 14px; color: var(--ink2); line-height: 1.75; }
.five-q-result-text strong { color: var(--teal); }

    .skill-btn-meta {
      display: inline-flex; align-items: center; gap: 7px;
      font-family: 'JetBrains Mono', monospace;
      font-size: 11px; letter-spacing: 0.04em;
      color: var(--teal);
      background: var(--teal-light);
      border: 1px solid rgba(var(--teal-rgb),0.2);
      padding: 8px 16px; border-radius: 8px;
      cursor: pointer;
      transition: all 0.18s;
      text-decoration: none;
      margin-left: auto;
      align-self: center;
    }
    .skill-btn-meta:hover {
      background: var(--teal);
      color: white;
      border-color: var(--teal);
    }
    .skill-btn-meta svg {
      width: 14px; height: 14px;
      stroke: currentColor; fill: none;
      stroke-width: 2; stroke-linecap: round; stroke-linejoin: round;
    }

/* Nav fav button */
.nav-fav-group { display: flex; align-items: center; gap: 8px; }
.nav-fav-btn {
  font-family: 'JetBrains Mono', monospace; font-size: 10px; letter-spacing: 0.04em;
  color: var(--ink3); background: var(--paper2, #f2f0eb); border: 1px solid var(--line);
  padding: 3px 10px; border-radius: 3px; cursor: pointer; transition: all 0.15s;
  display: flex; align-items: center; gap: 4px;
}
.nav-fav-btn:hover { background: var(--paper3, #e8e5de); color: var(--ink2); }
.nav-fav-btn.is-fav { color: #b88010; background: #fdf8ec; border-color: #e8c870; }
/* SVG Assemble animation */
.hero .float-svg svg > * {
  opacity: 0; transform-origin: center;
  animation: assembleIn 0.8s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}
.hero .float-svg svg > *:nth-child(odd)  { transform: translate(-30px, -20px) rotate(-90deg); }
.hero .float-svg svg > *:nth-child(even) { transform: translate(30px, 20px) rotate(90deg); }
.hero .float-svg svg > *:nth-child(1)  { animation-delay: 0.05s; }
.hero .float-svg svg > *:nth-child(2)  { animation-delay: 0.11s; }
.hero .float-svg svg > *:nth-child(3)  { animation-delay: 0.17s; }
.hero .float-svg svg > *:nth-child(4)  { animation-delay: 0.23s; }
.hero .float-svg svg > *:nth-child(5)  { animation-delay: 0.29s; }
.hero .float-svg svg > *:nth-child(6)  { animation-delay: 0.35s; }
.hero .float-svg svg > *:nth-child(7)  { animation-delay: 0.41s; }
.hero .float-svg svg > *:nth-child(8)  { animation-delay: 0.47s; }
.hero .float-svg svg > *:nth-child(9)  { animation-delay: 0.53s; }
.hero .float-svg svg > *:nth-child(10) { animation-delay: 0.59s; }
.hero .float-svg svg > *:nth-child(11) { animation-delay: 0.65s; }
.hero .float-svg svg > *:nth-child(12) { animation-delay: 0.71s; }
@keyframes assembleIn { to { opacity: 1; transform: translate(0,0) rotate(0deg); } }

  .related-tools { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 24px; }

  .rt-e-list { margin-top: 24px; }
  .rt-e-item {
    display: flex; align-items: baseline; gap: 12px;
    padding: 10px 0; border-bottom: 1px dashed var(--line);
    text-decoration: none; transition: background 0.15s;
  }
  .rt-e-item:last-child { border-bottom: none; }
  .rt-e-item:hover { background: var(--paper2); margin: 0 -12px; padding: 10px 12px; border-radius: 4px; }
  .rt-e-name { font-size: 14px; font-weight: 600; color: var(--ink); white-space: nowrap; flex-shrink: 0; }
  .rt-e-sep { font-size: 11px; color: var(--line); flex-shrink: 0; }
  .rt-e-rel { font-size: 13px; color: var(--ink2); line-height: 1.5; }
  .rt-e-arrow { font-size: 11px; color: var(--ink3); opacity: 0.3; margin-left: auto; flex-shrink: 0; }
  .rt-e-item:hover .rt-e-arrow { opacity: 1; color: var(--amber); }

  @media (max-width: 768px) {
    .skill-btn-meta { display: none !important; }
    .nav-fav-btn { display: none !important; }
    .nav-badge { display: none !important; }
  }
